WITH enriched AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, ROW_NUMBER() OVER (PARTITION BY status ORDER BY order_date, id) AS row_seq, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY shipping_fee DESC, id) AS seq_no FROM orders), with_windows AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, row_seq, seq_no, LEAD(seq_no, 2) OVER (PARTITION BY customer_id ORDER BY seq_no, id) AS next_seq_no, RANK() OVER (ORDER BY shipping_fee) AS shipping_fee_rank, LAG(seq_no, 2) OVER (PARTITION BY customer_id ORDER BY row_seq, id) AS prev_seq_no, NTILE(10) OVER (PARTITION BY customer_id, channel ORDER BY amount DESC, id) AS amount_bucket, ROUND(row_seq / SUM(row_seq) OVER (PARTITION BY store_id, channel), 4) AS row_seq_share FROM enriched), scored AS (SELECT *, ROUND(amount_bucket / SUM(amount_bucket) OVER (PARTITION BY channel), 4) AS amount_bucket_share, SUM(next_seq_no) OVER (PARTITION BY customer_id ORDER BY prev_seq_no, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_next_seq_no FROM with_windows), matched_keys AS (SELECT customer_id, store_id FROM scored INTERSECT SELECT customer_id, store_id FROM orders WHERE shipping_fee BETWEEN 11 AND 23), kept_rows AS (SELECT s.* FROM scored s INNER JOIN matched_keys k ON s.customer_id = k.customer_id AND s.store_id = k.store_id) SELECT seq_no, SIZE(COLLECT_SET(channel)) AS num_channels, APPROX_PERCENTILE(seq_no, ARRAY(0.25, 0.5, 0.75)) AS seq_no_quartiles, MAX(seq_no) FILTER (WHERE status = 'COMPLETED') AS completed_max_seq_no FROM kept_rows GROUP BY seq_no ORDER BY num_channels DESC
